// ===== MODELO ASISTENTE: menú guiado, sin IA =====
const cfg = $input.first().json; const body = (cfg._in && cfg._in.body) || {};
// ===== Funciones comunes (no editar) =====
const sd = $getWorkflowStaticData('global');
sd.sesiones = sd.sesiones || {}; sd.codigos = sd.codigos || {}; sd.pedidos = sd.pedidos || {}; sd.vistos = sd.vistos || []; sd.consecutivo = sd.consecutivo || 1000;
const ahora = Date.now();
sd.rev = ahora;
const plata = n => (cfg.moneda || '$') + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const soloNum = s => String(s || '').replace(/\D/g, '');
const chatDueno = soloNum(cfg.whatsappDueno) + '@c.us';
const sesionWaha = () => cfg.conexion.sesion || 'default';
// lista: { titulo, descripcion, boton, secciones:[{titulo, filas:[{id,titulo,descripcion}]}] }
const msg = (chatId, text, espera, lista) => {
  const base = { chatId, text, wahaUrl: String(cfg.conexion.wahaUrl).replace(/\/$/, ''),
    apiKey: cfg.conexion.wahaApiKey, sesion: sesionWaha(), espera: espera || 0 };
  if (lista && cfg.menuLista) {
    const mensaje = { description: lista.descripcion || text, button: lista.boton || 'Ver opciones',
      sections: lista.secciones.map(s => ({ title: s.titulo || ' ', rows: s.filas.map(f => ({
        rowId: String(f.id), title: f.titulo.length > 24 ? f.titulo.slice(0, 23) + '…' : f.titulo,
        description: f.descripcion || '' })) })) };
    const tit = lista.titulo !== undefined ? lista.titulo : (cfg.tituloLista !== undefined ? cfg.tituloLista : cfg.nombre);
    if (tit) mensaje.title = tit;      // WhatsApp exige encabezado: vacío o ausente rechaza la lista entera
    if (lista.pie) mensaje.footer = lista.pie;
    return { json: { ...base, endpoint: 'sendList', cuerpo: { session: sesionWaha(), chatId, message: mensaje } } };
  }
  return { json: { ...base, endpoint: 'sendText', cuerpo: { session: sesionWaha(), chatId, text } } };
};
// ===== Adjuntos: imagen, archivo (PDF), audio, video =====
const MIME = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif',
  pdf: 'application/pdf', mp3: 'audio/mpeg', ogg: 'audio/ogg; codecs=opus', opus: 'audio/ogg; codecs=opus',
  m4a: 'audio/mp4', mp4: 'video/mp4',
  doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' };
const ENDPOINT = { imagen: 'sendImage', archivo: 'sendFile', audio: 'sendVoice', video: 'sendVideo' };
const finUrl = u => String(u || '').split('?')[0].split('#')[0].split('/').pop() || 'archivo';
// adjunto('imagen', 'https://.../foto.jpg', 'texto que acompaña')
// El texto va como pie de foto; si WhatsApp rechaza el archivo, el nodo Respaldo lo manda como texto normal.
const adjunto = (chatId, tipo, url, texto, nombre, espera) => {
  const ep = ENDPOINT[tipo] || 'sendFile';
  const arch = finUrl(url);
  const ext = (arch.split('.').pop() || '').toLowerCase();
  const cuerpo = { session: sesionWaha(), chatId,
    file: { mimetype: MIME[ext] || 'application/octet-stream', url: String(url), filename: nombre || arch } };
  if (texto && ep !== 'sendVoice') cuerpo.caption = texto;
  return { json: { chatId, text: texto || '', wahaUrl: String(cfg.conexion.wahaUrl).replace(/\/$/, ''),
    apiKey: cfg.conexion.wahaApiKey, sesion: sesionWaha(), espera: espera || 0, endpoint: ep, cuerpo } };
};
const avisoDueno = (texto, espera) => msg(chatDueno, (sd.probando ? '🔒 _Solo lo ves tú, el cliente no ve esto:_\n\n' : '') + texto, espera);
const productos = (cfg.catalogo || []).flatMap(c => (c.productos || []).map(p => ({ ...p, categoria: c.categoria })));

sd.ritmo = sd.ritmo || {}; sd.silencio = sd.silencio || {};
let avisoBloqueo = null;                // aviso al dueño cuando se silencia un chat
const coincide = (lista, ids) => (lista || []).map(soloNum).filter(Boolean).some(n => ids.some(i => i === n || i.endsWith(n)));
function leerMensaje() {
  if (body.event && body.event !== 'message') return null;
  const p = body.payload || {};
  const from = String(p.from || '');
  if (!from || p.fromMe || from.endsWith('@g.us') || from.includes('broadcast') || from.includes('newsletter')) return null;
  if (p.id) {
    if (sd.vistos.includes(p.id)) return null;
    sd.vistos.push(p.id);
    if (sd.vistos.length > 300) sd.vistos = sd.vistos.slice(-150);
  }
  // Números con los que se identifica quien escribe (el chat puede venir como @lid)
  const clave = (p._data && p._data.key) || {};
  const ids = [from, p.participant, ...Object.values(clave)].filter(v => typeof v === 'string').map(v => soloNum(v.split(/[:@]/)[0])).filter(Boolean);
  const deDueno = coincide((cfg.idsDueno || []).length ? cfg.idsDueno : [cfg.whatsappDueno], ids);
  if (!deDueno) {
    if (coincide(cfg.noResponderA, ids)) return null;                                   // lista de bloqueados
    if ((cfg.soloResponderA || []).length && !coincide(cfg.soloResponderA, ids)) {   // modo prueba
      sd.avisados = sd.avisados || {};                                  // avisa al dueño el identificador, una vez por hora
      if (ahora - (sd.avisados[from] || 0) > 3600e3) {
        sd.avisados[from] = ahora;
        avisoBloqueo = msg(chatDueno, `📵 *Modo prueba*\n\nIgnoré un mensaje de un número que no está autorizado.\n\nSu identificador es:\n*${ids[0]}*\n\nSi quieres que el bot le responda, agrégalo a *soloResponderA* en la Configuración del negocio.`);
      }
      return null;
    }
  }
  // Anti-ciclo: si un chat escribe demasiado rápido (otro bot), se silencia
  if (deDueno) return { chatId: from, texto: String(p.body || '').trim(), deDueno };
  if ((sd.silencio[from] || 0) > ahora) return null;
  const r = (sd.ritmo[from] || []).filter(t => ahora - t < 60e3); r.push(ahora); sd.ritmo[from] = r;
  if (r.length > (cfg.maxMensajesPorMinuto || 15)) {
    sd.silencio[from] = ahora + 60 * 60e3; delete sd.ritmo[from];
    avisoBloqueo = avisoDueno(`⚠️ Silencié 1 hora un chat que escribía demasiado rápido (posible bot): ${from}`);
    return null;
  }
  return { chatId: from, texto: String(p.body || '').trim(), deDueno };
}
function sesion(chatId) {
  let s = sd.sesiones[chatId];
  if (!s || ahora - s.t > 6 * 3600e3) {
    s = { paso: 'nuevo', carrito: [], d: {}, pausaHasta: s ? s.pausaHasta || 0 : 0, dia: '', n: 0 };
    sd.sesiones[chatId] = s;
  }
  s.t = ahora;
  return s;
}
function limpiar() {
  for (const k of Object.keys(sd.sesiones)) if (ahora - sd.sesiones[k].t > 7 * 86400e3) delete sd.sesiones[k];
  sd.avisados = sd.avisados || {};
  for (const k of Object.keys(sd.avisados)) if (ahora - sd.avisados[k] > 86400e3) delete sd.avisados[k];
  for (const k of Object.keys(sd.silencio)) if (sd.silencio[k] < ahora) delete sd.silencio[k];
  for (const k of Object.keys(sd.ritmo)) if (!sd.ritmo[k].some(t => ahora - t < 60e3)) delete sd.ritmo[k];
  for (const k of Object.keys(sd.pedidos)) if (ahora - sd.pedidos[k].creado > 60 * 86400e3) delete sd.pedidos[k];
}
function costoEnvio(ciudad, subtotal) {
  const e = cfg.envios || {};
  if (cfg.pedirDireccion === false) return 0;
  if (e.gratisDesde && subtotal >= e.gratisDesde) return 0;
  const local = ((e.local && e.local.ciudades) || []).some(c => norm(c) === norm(ciudad));
  return local ? (e.local.costo || 0) : ((e.nacional && e.nacional.costo) || 0);
}
function linkPedido(p) {
  const u = String(cfg.urlPublica || '').trim().replace(/\/$/, '');
  return u ? `${u}/webhook/${cfg.rutaPedido}?p=${p.id}&t=${p.token}` : '';
}
function crearPedido(chatId, d) {
  limpiar();
  const id = `${cfg.prefijoPedido || 'P'}-${++sd.consecutivo}`;
  const subtotal = d.items.reduce((a, i) => a + i.precio * i.cantidad, 0);
  const envio = costoEnvio(d.ciudad, subtotal);
  const p = { id, token: Math.random().toString(36).slice(2, 10), chatId, items: d.items, subtotal, envio, total: subtotal + envio,
    nombre: d.nombre || '', ciudad: d.ciudad || '', direccion: d.direccion || '', pago: d.pago || '', estado: 'pendiente', creado: ahora };
  sd.pedidos[id] = p;
  return p;
}
function textoPedido(p) {
  const l = [`🧾 *Pedido ${p.id}*`];
  for (const i of p.items) l.push(`• ${i.cantidad} x ${i.nombre}${i.opcion ? ' (' + i.opcion + ')' : ''} — ${plata(i.precio * i.cantidad)}`);
  if (cfg.pedirDireccion !== false) l.push(`Envío: ${p.envio ? plata(p.envio) : 'gratis'}`);
  l.push(`*Total: ${plata(p.total)}*`, '', `Nombre: ${p.nombre}`);
  if (p.ciudad) l.push(`Ciudad: ${p.ciudad}`);
  if (p.direccion) l.push(`Dirección: ${p.direccion}`);
  if (p.pago) l.push(`Pago: ${p.pago}`);
  return l.join('\n');
}
function pedirConfirmacion(p) {
  const link = linkPedido(p);
  return textoPedido(p) + '\n\n' + (link
    ? `👉 Para confirmar tu pedido abre este link:\n${link}\n\n(También puedes responder *CONFIRMO*)`
    : `👉 Para confirmar tu pedido responde *CONFIRMO*`);
}
function pendiente(chatId) {
  return Object.values(sd.pedidos).filter(p => p.chatId === chatId && p.estado === 'pendiente').sort((a, b) => b.creado - a.creado)[0];
}
function confirmar(p) {
  p.estado = 'confirmado'; p.confirmado = ahora;
  const pago = (cfg.pagos || []).find(x => norm(x.nombre) === norm(p.pago));
  const tel = p.chatId.endsWith('@c.us') ? `\nCliente: https://wa.me/${soloNum(p.chatId)}` : '';
  return [
    msg(p.chatId, `✅ *Pedido ${p.id} confirmado.* ¡Gracias, ${p.nombre.split(' ')[0]}!` + (pago ? `\n\n💳 ${pago.nombre}: ${pago.instrucciones}` : '') + `\n\nTe avisamos cuando esté en camino.`),
    msg(chatDueno, `🔔 *NUEVO PEDIDO CONFIRMADO*\n\n${textoPedido(p)}${tel}`)
  ];
}
// Entiende "15/11 2pm", "mañana 9am", "hoy 4:30 pm", "15/11/2026 14:00"
function leerCita(txt) {
  const t = norm(txt).replace(/\s+a\s+las\s+/, ' ').trim();
  const hm = /(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?(?!\d)/.exec(t.replace(/^\d{1,2}[/-]\d{1,2}([/-]\d{2,4})?/, ''));
  if (!hm) return null;
  let h = Number(hm[1]); const mi = Number(hm[2] || 0);
  const suf = (hm[3] || '').replace(/\./g, '');
  if (suf.startsWith('p') && h < 12) h += 12;
  if (suf.startsWith('a') && h === 12) h = 0;
  if (!suf && h <= 7) h += 12;                 // "a las 3" en un negocio es a las 3 de la tarde
  const L = localDe(ahora);
  if (!L || h > 23 || mi > 59) return null;
  let dia = L.dia, fecha = L.fecha, dias = 0;
  const f = /(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?/.exec(t);
  if (f) {
    const yy = f[3] ? (f[3].length === 2 ? 2000 + Number(f[3]) : Number(f[3])) : Number(L.fecha.slice(0, 4));
    fecha = `${yy}-${String(Number(f[2])).padStart(2, '0')}-${String(Number(f[1])).padStart(2, '0')}`;
  } else if (/\bmanana\b/.test(t)) dias = 1;
  else if (/\bpasado\b/.test(t)) dias = 2;
  else if (!/\bhoy\b/.test(t) && (h + mi / 60) < L.h) dias = 1;    // una hora que ya pasó es de mañana
  if (!f && dias) { const d = localDe(ahora + dias * 86400e3); if (d) fecha = d.fecha; }
  const ms = Date.parse(`${fecha}T${String(h).padStart(2, '0')}:${String(mi).padStart(2, '0')}:00${desfase()}`);
  if (!ms || isNaN(ms)) return null;
  const h12 = h % 12 === 0 ? 12 : h % 12;
  const dd = fecha.split('-');
  return { t: ms, fecha: `${Number(dd[2])}/${Number(dd[1])}`, hora: `${h12}:${String(mi).padStart(2, '0')} ${h < 12 ? 'a.m.' : 'p.m.'}` };
}
// Desfase horario del negocio en formato +hh:mm, calculado contra UTC
function desfase() {
  const d = new Date(ahora);
  const loc = new Date(d.toLocaleString('en-US', { timeZone: cfg.zonaHoraria || 'America/Bogota' }));
  const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
  const min = Math.round((loc - utc) / 60000);
  const s = min < 0 ? '-' : '+', a = Math.abs(min);
  return `${s}${String(Math.floor(a / 60)).padStart(2, '0')}:${String(a % 60).padStart(2, '0')}`;
}
const AYUDA = `🎛️ *Mandos del bot*

*clientes* — quién está esperando
*#PC1 texto* — hablar con ese cliente
*fin* — cerrar la conversación

*pausa* — el bot deja de responder
*pausa 30* — pausa 30 minutos y vuelve solo
*seguir* — vuelve a responder

*agenda #PC1 15/11 2pm* — cita con recordatorio

*probar* — te atiende como si fueras cliente
*estado* — cómo está todo ahora mismo`;
const minPuente = () => cfg.puenteMinutos || 120;
const sigla = () => String(cfg.prefijoPedido || '').toUpperCase().replace(/[^A-Z]/g, '');
function codigoDe(chatId) {
  for (const k of Object.keys(sd.codigos)) if (sd.codigos[k] === chatId) return k;
  sd.nCodigo = (sd.nCodigo || 0) + 1;
  const k = sigla() + sd.nCodigo;
  sd.codigos[k] = chatId;
  return k;
}
const buscarCodigo = txt => {                      // acepta #PC1, #pc1 o #1
  const t = String(txt || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  for (const k of Object.keys(sd.codigos)) if (k.toUpperCase() === t || k.toUpperCase() === sigla() + t) return k;
  return null;
};
function cerrarPuente() {
  if (!sd.activo) return null;
  const c = codigoDe(sd.activo), s = sesion(sd.activo);
  s.pausaHasta = 0; s.paso = 'menu'; s.fallos = 0;
  sd.activo = null;
  return c;
}
function pasarAHumano(chatId, s, motivo) {
  s.pausaHasta = ahora + (cfg.pausaHumanoMin || 120) * 60e3;
  const c = codigoDe(chatId);
  const nom = s.nombre || (s.d && s.d.nombre) || '';
  const quien = nom ? ` — ${nom}` : '';
  return avisoDueno(`🙋 *${cfg.nombre} · Cliente #${c}*${quien}\nMotivo: ${motivo}\n\nEscribe *#${c}* para hablar con él. Lo que escribas le llega como ${cfg.nombre}.`);
}
// Mensaje del dueño: maneja el puente. Devuelve la lista de mensajes a enviar.
function mandoDueno(texto) {
  const t = String(texto || '').trim();
  const n = norm(t);
  if (sd.activo && ahora - (sd.puenteT || 0) > minPuente() * 60e3) {
    const c = cerrarPuente();
    return [msg(chatDueno, `⌛ Cerré solo el puente con el cliente #${c} por inactividad. El bot vuelve a atenderlo.`)];
  }
  if (/^(fin|cerrar|salir|listo)$/.test(n)) {
    const c = cerrarPuente();
    return [msg(chatDueno, c ? `✅ Puente cerrado con el cliente #${c}. El bot vuelve a atenderlo.` : 'No tienes ningún puente abierto.')];
  }
  // agenda #PC1 15/11 2pm   ·   con el puente abierto basta: agenda 15/11 2pm
  const ag = /^(?:agenda|agendar|cita)\s+(?:#?([a-z]*\d+)\s+)?(.+)$/i.exec(t);
  if (ag) {
    const dest = ag[1] ? buscarCodigo('#' + ag[1]) : sd.activo;
    if (!dest) return [msg(chatDueno, 'No sé para quién es la cita. Escribe *agenda #PC1 15/11 2pm*, o abre el puente con *#PC1* y luego *agenda 15/11 2pm*.')];
    const c = leerCita(ag[2]);
    if (!c) return [msg(chatDueno, 'No entendí la fecha. Prueba así:\n\n*agenda 15/11 2pm*\n*agenda mañana 9am*\n*agenda hoy 4:30pm*')];
    const ses = sesion(dest);
    sd.citas = sd.citas || {};
    sd.citas[dest] = { t: c.t, hora: c.hora, fecha: c.fecha, servicio: ses.servicio || 'tu servicio', nombre: ses.nombre || '' };
    const falta = Math.round((c.t - ahora) / 36e5);
    return [msg(chatDueno, `📅 Cita guardada para *${c.fecha}* a las *${c.hora}* con #${codigoDe(dest)}.\n\n${falta > 3 ? 'Le recuerdo 3 horas antes.' : 'Falta menos de 3 horas: no alcanzo a recordarle.'}`),
      msg(dest, `📅 *Cita confirmada*\n\nTe esperamos el *${c.fecha}* a las *${c.hora}*.\n\nSi algo cambia, escríbeme por aquí.`)];
  }
  const pa = /^(pausa|pausar|apaga|apagar|detener|stop)\s*(\d+)?$/.exec(n);
  if (pa) {
    const min = parseInt(pa[2], 10);
    sd.pausado = min ? ahora + min * 60e3 : 8640000000000000;
    return [msg(chatDueno, `⏸️ *Bot en pausa.*\n\nNo le responde a nadie${min ? ` durante ${min} minutos` : ''}. Los mensajes que lleguen quedan sin contestar.\n\nEscribe *seguir* para activarlo${min ? ' antes' : ''}.`)];
  }
  if (/^(seguir|reanudar|activar|prender|encender|continuar|start)$/.test(n)) {
    const estaba = (sd.pausado || 0) > ahora;
    sd.pausado = 0;
    return [msg(chatDueno, estaba ? '▶️ *Bot activo otra vez.* Ya vuelve a responder.' : 'El bot no estaba en pausa: sigue respondiendo normal.')];
  }
  if (/^(estado|status)$/.test(n)) {
    const H = estadoHorario();
    const enPausa = (sd.pausado || 0) > ahora;
    const falta = enPausa && sd.pausado < 8000000000000000 ? ` (le faltan ${Math.ceil((sd.pausado - ahora) / 60e3)} min)` : '';
    return [msg(chatDueno, `📊 *${cfg.nombre}*\n\n` +
      `Bot: ${enPausa ? '⏸️ en pausa' + falta : (enHorarioBot() ? '✅ respondiendo' : '😴 fuera de su horario')}\n` +
      `Atención: ${H.abierto ? '🟢 abierto' : '🔴 cerrado, vuelve ' + (H.texto || 'pronto')}\n` +
      `Modo cliente: ${sd.probando ? '🧪 activado' : 'no'}\n` +
      `Puente: ${sd.activo ? 'abierto con #' + codigoDe(sd.activo) : 'cerrado'}\n` +
      `Clientes atendidos: ${Object.keys(sd.codigos).length}`)];
  }
  if (/^(ayuda|comandos|help)$/.test(n)) return [msg(chatDueno, AYUDA)];
  if (/^(clientes|lista|menu)$/.test(n)) {
    const l = Object.keys(sd.codigos).map(k => {
      const s = sd.sesiones[sd.codigos[k]] || {};
      const esp = s.pausaHasta > ahora ? ' (esperándote)' : '';
      return `*#${k}* ${s.nombre || (s.d && s.d.nombre) || 'Sin nombre'}${esp}`;
    });
    return [msg(chatDueno, (l.length ? `👥 *Clientes de ${cfg.nombre}*\n` + l.join('\n') : 'Todavía no hay clientes.') +
      `\n\n*#número* para hablar con uno\n*fin* para cerrar el puente\n*ayuda* para ver todos los mandos`)];
  }
  const abrir = /^#\s*([a-zA-Z]*\d+)\s*([\s\S]*)$/.exec(t);
  if (abrir) {
    const c = buscarCodigo(abrir[1]), id = c && sd.codigos[c];
    if (!id) return [msg(chatDueno, `No encuentro el cliente #${abrir[1]}. Escribe *clientes* para ver la lista.`)];
    sd.activo = id; sd.puenteT = ahora;
    sesion(id).pausaHasta = ahora + minPuente() * 60e3;
    const resto = abrir[2].trim();
    const aviso = msg(chatDueno, `🔗 Puente abierto con el cliente #${c}. Todo lo que escribas le llega a él. Escribe *fin* para cerrar.`);
    return resto ? [msg(id, resto), aviso] : [aviso];
  }
  if (sd.activo) {
    sd.puenteT = ahora;
    sesion(sd.activo).pausaHasta = ahora + minPuente() * 60e3;
    return [msg(sd.activo, t)];
  }
  return [msg(chatDueno, `No hay ningún puente abierto.\n\n` + AYUDA)];
}
// Decide qué hacer con un mensaje del dueño: mandos del puente, o atenderlo como cliente de prueba
function rutaDueno(m) {
  const n = norm(m.texto);
  if (sd.probando) {
    if (/^(fin|salir|terminar)$/.test(n)) {
      sd.probando = false; const s = sesion(m.chatId); s.paso = 'nuevo'; s.carrito = []; s.d = {}; s.pausaHasta = 0;
      return [msg(chatDueno, '✅ Saliste del modo cliente. Vuelves a manejar el puente desde aquí.')];
    }
    return null;                                   // sigue el flujo normal, como si fuera un cliente
  }
  if (/^(probar|prueba|modo cliente)$/.test(n)) {
    sd.probando = true; const s = sesion(m.chatId); s.paso = 'nuevo'; s.carrito = []; s.d = {}; s.pausaHasta = 0; s.fallos = 0;
    return [msg(chatDueno, '🧪 *Modo cliente activado.* Te atiendo como si fueras un cliente, para que pruebes el bot.\n\nEscribe *fin* cuando quieras volver.')];
  }
  return mandoDueno(m.texto);
}
// Mensaje de un cliente con el puente abierto: se lo reenvío al dueño
function reenviarAlDueno(m) {
  sd.puenteT = ahora;
  sesion(m.chatId).pausaHasta = ahora + minPuente() * 60e3;
