// ===== Horario de atención =====
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
function localDe(ms) {
  const s = new Date(ms).toLocaleString('en-US', { timeZone: cfg.zonaHoraria || 'America/Bogota', hour12: false,
    weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  const m = /^(\w{3}),?\s*(\d{2})\/(\d{2})\/(\d{4}),?\s*(\d{1,2}):(\d{2})/.exec(s);
  if (!m) return null;
  const W = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { dia: W[m[1]], fecha: `${m[4]}-${m[2]}-${m[3]}`, h: (Number(m[5]) % 24) + Number(m[6]) / 60 };
}
function festivosCO(anio) {                       // festivos de Colombia, con la ley Emiliani
  const out = {};
  const add = (m, d) => { out[`${anio}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`] = 1; };
  const lunes = (m, d) => { const x = new Date(Date.UTC(anio, m - 1, d)); const w = x.getUTCDay();
    if (w !== 1) x.setUTCDate(x.getUTCDate() + ((8 - w) % 7)); add(x.getUTCMonth() + 1, x.getUTCDate()); };
  [[1, 1], [5, 1], [7, 20], [8, 7], [12, 8], [12, 25]].forEach(x => add(x[0], x[1]));
  [[1, 6], [3, 19], [6, 29], [8, 15], [10, 12], [11, 1], [11, 11]].forEach(x => lunes(x[0], x[1]));
  const a = anio % 19, b = Math.floor(anio / 100), c = anio % 100, q = Math.floor(b / 4), e = b % 4,
    g = Math.floor((8 * b + 13) / 25), h = (19 * a + b - q - g + 15) % 30, i = Math.floor(c / 4), k = c % 4,
    l = (32 + 2 * e + 2 * i - h - k) % 7, u = Math.floor((a + 11 * h + 19 * l) / 433),
    mes = Math.floor((h + l - 7 * u + 90) / 25), dia = (h + l - 7 * u + 33 * mes + 19) % 32;
  const p = Date.UTC(anio, mes - 1, dia);                      // domingo de Pascua
  for (const n of [-3, -2, 43, 64, 71]) {                      // jueves y viernes santo, ascensión, corpus, sagrado corazón
    const x = new Date(p + n * 86400e3); add(x.getUTCMonth() + 1, x.getUTCDate());
  }
  return out;
}
function franjasDe(dia, fecha) {
  if (cfg.festivosColombia) {
    const anio = Number(fecha.slice(0, 4));
    sd.festivos = sd.festivos || {};
    sd.festivos[anio] = sd.festivos[anio] || festivosCO(anio);
    if (sd.festivos[anio][fecha]) return [];
  }
  if ((cfg.diasCerrados || []).includes(fecha)) return [];
  return (cfg.horarioAtencion || {})[dia] || [];
}
// Horas en que el bot responde. Fuera de ahí se queda callado y contesta el mensaje de ausencia de WhatsApp.
// No mira festivos a propósito: en festivo el bot sí atiende y avisa cuándo vuelve una persona.
function enHorarioBot() {
  if (!cfg.horarioBot) return true;
  const L = localDe(ahora);
  if (!L) return true;
  return (cfg.horarioBot[L.dia] || []).some(f => L.h >= f[0] && L.h < f[1]);
}
// { abierto: true/false, texto: "mañana desde las 8:00 a.m." }
function estadoHorario() {
  const L = cfg.horarioAtencion ? localDe(ahora) : null;
  if (!L) return { abierto: true, texto: '' };
  if (franjasDe(L.dia, L.fecha).some(f => L.h >= f[0] && L.h < f[1])) return { abierto: true, texto: '' };
  for (let i = 0; i < 9; i++) {
    const d = localDe(ahora + i * 86400e3); if (!d) break;
    for (const f of franjasDe(d.dia, d.fecha)) {
      if (i === 0 && L.h >= f[0]) continue;
      const hh = Math.floor(f[0]), mi = Math.round((f[0] - hh) * 60);
      const reloj = `${hh > 12 ? hh - 12 : hh}:${String(mi).padStart(2, '0')} ${hh >= 12 ? 'p.m.' : 'a.m.'}`;
      return { abierto: false, texto: `${i === 0 ? 'hoy' : i === 1 ? 'mañana' : 'el ' + DIAS[d.dia]} desde las ${reloj}` };
    }
  }
  return { abierto: false, texto: '' };
}

