      msg(dest, `📅 *Cita confirmada*\n\nTe esperamos el *${c.fecha}* a las *${c.hora}*.\n\nSi algo cambia, escríbeme por aquí.`)];
  }
  const pa = /^(pausa|pausar|apaga|apagar|detener|stop)\s*(\d+)?$/.exec(n);
  if (pa) {
    const min = parseInt(pa[2], 10);
    sd.pausado = min ? ahora + min * 60e3 : 8640000000000000;
    return [msg(chatDueno, `⏸️ *Bot en pausa.*\n\nNo le responde a nadie${min ? ` durante ${min} minutos` : ''}. Los mensajes que lleguen quedan sin contestar.\n\nEscribe *seguir* para activarlo${min ? ' antes' : ''}.`)];
  }
  if (/^(seguir|reanudar|activar|prender|encender|continuar|start)$/.test(n)) {
    const estaba = (sd.pausado || 0) > ahora;
    sd.pausado = 0;
    return [msg(chatDueno, estaba ? '▶️ *Bot activo otra vez.* Ya vuelve a responder.' : 'El bot no estaba en pausa: sigue respondiendo normal.')];
  }
  if (/^(estado|status)$/.test(n)) {
    const H = estadoHorario();
    const enPausa = (sd.pausado || 0) > ahora;
    const falta = enPausa && sd.pausado < 8000000000000000 ? ` (le faltan ${Math.ceil((sd.pausado - ahora) / 60e3)} min)` : '';
    return [msg(chatDueno, `📊 *${cfg.nombre}*\n\n` +
      `Bot: ${enPausa ? '⏸️ en pausa' + falta : (enHorarioBot() ? '✅ respondiendo' : '😴 fuera de su horario')}\n` +
      `Atención: ${H.abierto ? '🟢 abierto' : '🔴 cerrado, vuelve ' + (H.texto || 'pronto')}\n` +
      `Modo cliente: ${sd.probando ? '🧪 activado' : 'no'}\n` +
      `Puente: ${sd.activo ? 'abierto con #' + codigoDe(sd.activo) : 'cerrado'}\n` +
      `Clientes atendidos: ${Object.keys(sd.codigos).length}`)];
  }
  if (/^(ayuda|comandos|help)$/.test(n)) return [msg(chatDueno, AYUDA)];
  if (/^(clientes|lista|menu)$/.test(n)) {
    const l = Object.keys(sd.codigos).map(k => {
      const s = sd.sesiones[sd.codigos[k]] || {};
      const esp = s.pausaHasta > ahora ? ' (esperándote)' : '';
      return `*#${k}* ${s.nombre || (s.d && s.d.nombre) || 'Sin nombre'}${esp}`;
    });
    return [msg(chatDueno, (l.length ? `👥 *Clientes de ${cfg.nombre}*\n` + l.join('\n') : 'Todavía no hay clientes.') +
      `\n\n*#número* para hablar con uno\n*fin* para cerrar el puente\n*ayuda* para ver todos los mandos`)];
  }
  const abrir = /^#\s*([a-zA-Z]*\d+)\s*([\s\S]*)$/.exec(t);
  if (abrir) {
    const c = buscarCodigo(abrir[1]), id = c && sd.codigos[c];
    if (!id) return [msg(chatDueno, `No encuentro el cliente #${abrir[1]}. Escribe *clientes* para ver la lista.`)];
    sd.activo = id; sd.puenteT = ahora;
    sesion(id).pausaHasta = ahora + minPuente() * 60e3;
    const resto = abrir[2].trim();
    const aviso = msg(chatDueno, `🔗 Puente abierto con el cliente #${c}. Todo lo que escribas le llega a él. Escribe *fin* para cerrar.`);
    return resto ? [msg(id, resto), aviso] : [aviso];
  }
  if (sd.activo) {
    sd.puenteT = ahora;
    sesion(sd.activo).pausaHasta = ahora + minPuente() * 60e3;
    return [msg(sd.activo, t)];
  }
  return [msg(chatDueno, `No hay ningún puente abierto.\n\n` + AYUDA)];
}
